item.command:
/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
for folder in ['docs','docs/specs','docs/specs/arch']:
 f=Path(folder)/'AGENTS.md'
 if f.is_file(): print(f'INSTRUCTIONS {f}\\n{f.read_text()}')
files=sorted(Path('docs/specs/arch').glob('ARCH-*.md'))
print('ARCH count:',len(files))
for f in files:
 print(f'ARCH {f}\\n{f.read_text().split(\"---\",2)[1]}')
PY"

